BEGIN;
CREATE TABLE app.discrepancy_finding_revision(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,command_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),rule_revision text NOT NULL,source_document_id uuid NOT NULL,source_version_id uuid NOT NULL,match_revision_id uuid NOT NULL,state varchar(20) NOT NULL CHECK(state IN('actionable','none','insufficient','superseded')),price_pence bigint NOT NULL CHECK(price_pence BETWEEN 0 AND 1000000000000),quantity_pence bigint NOT NULL CHECK(quantity_pence BETWEEN 0 AND 1000000000000),total_pence bigint NOT NULL CHECK(total_pence BETWEEN 0 AND 1000000000000),supersedes_id uuid,actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,source_version_id,match_revision_id,rule_revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,source_document_id)REFERENCES app.supplier_document(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,source_version_id)REFERENCES app.supplier_document_version(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,match_revision_id)REFERENCES app.supplier_match_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,supersedes_id)REFERENCES app.discrepancy_finding_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE app.discrepancy_review_outcome(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,finding_id uuid NOT NULL,command_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),outcome varchar(20) NOT NULL CHECK(outcome IN('dismissed','disputed')),reason text NOT NULL CHECK(length(trim(reason))>0),actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,finding_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,finding_id)REFERENCES app.discrepancy_finding_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE app.supplier_bill_supersession(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,command_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),original_fact_revision_id uuid NOT NULL,replacement_fact_revision_id uuid NOT NULL,confirmed_reduction_pence bigint NOT NULL CHECK(confirmed_reduction_pence BETWEEN 0 AND 1000000000000),actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,original_fact_revision_id,revision),UNIQUE(tenant_id,job_id,id),CHECK(original_fact_revision_id<>replacement_fact_revision_id),FOREIGN KEY(tenant_id,job_id,original_fact_revision_id)REFERENCES app.supplier_fact_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,replacement_fact_revision_id)REFERENCES app.supplier_fact_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['discrepancy_finding_revision','discrepancy_review_outcome','supplier_bill_supersession'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=current_setting(''app.tenant_id'')::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END$$;
COMMIT;
